// strict color validation: panics on invalid, returns parsed (r,g,b,a) on valid
fn validate_strict_color(color: &str) -> (u8,u8,u8,u8) {
    // must be #RRGGBB (len 7) or #RRGGBBAA (len 9), starting with #
    if color.len() != 7 && color.len() != 9 {
        panic_color_invalid(color);
    }
    if !color.starts_with('#') {
        panic_color_invalid(color);
