fn crc_chunk(chunk_type: &[u8;4], data: &[u8]) -> u32 {
    let mut h = crc32fast::Hasher::new();
    h.update(chunk_type);
    h.update(data);
    h.finalize()
}

fn write_chunk(out: &mut Vec<u8>, chunk_type: &[u8;4], data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_be_bytes());
    out.extend_from_slice(chunk_type);
    out.extend_from_slice(data);
    let crc = crc_chunk(chunk_type, data);
    out.extend_from_slice(&crc.to_be_bytes());
}

fn encode_png(width: u32, height: u32, rgba: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(&[137,80,78,71,13,10,26,10]);
    let mut ihdr = Vec::new();
    ihdr.extend_from_slice(&width.to_be_bytes());
    ihdr.extend_from_slice(&height.to_be_bytes());
    ihdr.push(8); // bit depth
    ihdr.push(6); // color type RGBA
    ihdr.push(0);
    ihdr.push(0);
    ihdr.push(0);
    write_chunk(&mut out, b"IHDR", &ihdr);
    // raw scanlines
    let stride = (width as usize)*4;
    let mut raw = Vec::with_capacity((stride+1)*(height as usize));
    for y in 0..(height as usize) {
        raw.push(0); // filter None
        let start = y*stride;
        raw.extend_from_slice(&rgba[start..start+stride]);
    }
    // compress with flate2 (zlib, default level? Original likely uses default compression level 6? We'll use default)
    use flate2::{Compression, write::ZlibEncoder};
    use std::io::Write;
    let mut enc = ZlibEncoder::new(Vec::new(), Compression::default());
    enc.write_all(&raw).unwrap();
    let compressed = enc.finish().unwrap();
    write_chunk(&mut out, b"IDAT", &compressed);
    write_chunk(&mut out, b"IEND", &[]);
    out
}

fn parse_hex_color(s: &str) -> Option<(u8,u8,u8,u8)> {
    if (s.len()==7 || s.len()==9) && s.starts_with('#') {
        let hex = &s[1..];
        let mut vals = Vec::new();
        for i in (0..hex.len()).step_by(2) {
            let pair = &hex[i..i+2];
            match u8::from_str_radix(pair, 16) {
                Ok(v) => vals.push(v),
                Err(_) => return None,
            }
        }
        if vals.len()==3 {
            return Some((vals[0],vals[1],vals[2],255));
        } else if vals.len()==4 {
            return Some((vals[0],vals[1],vals[2],vals[3]));
        }
    }
    None
}

// simple hash for deterministic pixels
fn hash_str(s: &str) -> u64 {
    // FNV-1a
    let mut h: u64 = 14695981039346656037;
    for b in s.as_bytes() {
        h ^= *b as u64;
        h = h.wrapping_mul(1099511628211);
    }
    h
}
