                let idx = (y*(w as usize)+x)*4;
                rgba[idx] = r.wrapping_add(pat % 32);
                rgba[idx+1] = g.wrapping_add(pat % 32);
                rgba[idx+2] = b.wrapping_add(pat % 32);
                rgba[idx+3] = 255;
            }
        }
        png_bytes = encode_png(w, h, &rgba);
    }

    let output_bytes: Vec<u8>;
    if is_png {
        output_bytes = png_bytes.clone();
    } else if is_svg {
        let b64 = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, &png_bytes);
        let svg = format!("<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>", b64);
        output_bytes = svg.into_bytes();
    } else {
