        let html = format!("<img src=\"data:image/png;base64,{}\" />", b64);
        output_bytes = html.into_bytes();
    }

    match fs::write(&output, &output_bytes) {
        Ok(_) => {
            if !silent {
                print_success(&format!("Snapshot saved to {} successful!", output));
            }
            if print_eggs {
                print_egg();
            }
        }
        Err(e) => {
            print_error(&e.to_string());
            process::exit(1);
        }
    }
}
