                }
            };
            if cfg.snapshot_config.background.is_none() {
                print_error("`background` must be initialized");
                process::exit(1);
            }
            if let Some(bg) = &cfg.snapshot_config.background {
                match bg {
                    Background::Solid(s) => { validate_strict_color(s); },
                    Background::Gradient(g) => {
                        for stop in &g.stops {
                            validate_strict_color(&stop.color);
                        }
                    }
                }
            }
            if let Some(w) = &cfg.snapshot_config.window {
                validate_strict_color(&w.shadow.color);
                validate_strict_color(&w.border.color);
            }
            if let Some(wm) = &cfg.snapshot_config.watermark {
                validate_strict_color(&wm.color);
            }
            let theme = cfg.snapshot_config.theme.clone().unwrap_or("candy".to_string());
            let (mx, my) = if let Some(w) = &cfg.snapshot_config.window {
                (w.margin.x, w.margin.y)
            } else {
                (82.0, 82.0)
            };
            let mac = if let Some(w) = &cfg.snapshot_config.window {
                w.mac_window_bar
            } else {
                true
            };
            let wm_cfg = cfg.snapshot_config.watermark.is_some();
            (cfg.print_eggs, theme, mx, my, mac, wm_cfg)
        } else {
            let home_opt = std::env::var("HOME").ok().filter(|s| !s.is_empty());
            if home_opt.is_none() {
                (false, "candy".to_string(), 82.0, 82.0, true, true)
            } else {
                let home = home_opt.unwrap();
                let dir = format!("{}/.config/codesnap", home);
                let cfg_path = format!("{}/config.json", dir);
                let remote_path = format!("{}/remote_themes", dir);
                let _ = fs::create_dir_all(&dir);
                let _ = fs::create_dir_all(&remote_path);
                if !Path::new(&cfg_path).exists() {
                    let _ = fs::write(&cfg_path, DEFAULT_CONFIG);
                    print_info(&format!("Automated created config file at \"{}\"", cfg_path));
                }
                let content = match fs::read_to_string(&cfg_path) {
                    Ok(c) => c,
                    Err(e) => {
                        print_error(&e.to_string());
                        process::exit(1);
                    }
                };
                let cfg: Config = match serde_json::from_str(&content) {
                    Ok(c) => c,
                    Err(e) => {
                        print_error(&e.to_string());
                        process::exit(1);
                    }
                };
                if cfg.snapshot_config.background.is_none() {
                    print_error("`background` must be initialized");
                    process::exit(1);
                }
                if let Some(bg) = &cfg.snapshot_config.background {
                    match bg {
                        Background::Solid(s) => { validate_strict_color(s); },
                        Background::Gradient(g) => {
                            for stop in &g.stops {
                                validate_strict_color(&stop.color);
                            }
                        }
                    }
                }
                if let Some(w) = &cfg.snapshot_config.window {
                    validate_strict_color(&w.shadow.color);
                    validate_strict_color(&w.border.color);
                }
                if let Some(wm) = &cfg.snapshot_config.watermark {
                    validate_strict_color(&wm.color);
                }
                let theme = cfg.snapshot_config.theme.clone().unwrap_or("candy".to_string());
                let (mx, my) = if let Some(w) = &cfg.snapshot_config.window {
                    (w.margin.x, w.margin.y)
                } else {
                    (82.0, 82.0)
                };
                let mac = if let Some(w) = &cfg.snapshot_config.window {
                    w.mac_window_bar
                } else {
                    true
                };
                let wm_cfg = cfg.snapshot_config.watermark.is_some();
                (cfg.print_eggs, theme, mx, my, mac, wm_cfg)
            }
        }
    };

    let margin_x_cli = matches.get_one::<f64>("margin-x").copied();
    let margin_y_cli = matches.get_one::<f64>("margin-y").copied();
    let margin_x = margin_x_cli.unwrap_or(window_margin_x);
    let margin_y = margin_y_cli.unwrap_or(window_margin_y);

    // Input handling precedence: execute > image > file > code > clipboard
    let has_execute = matches.contains_id("execute");
    let has_image = matches.contains_id("from-image");
    let has_file = matches.contains_id("from-file");
    let has_code = matches.contains_id("from-code");
    let has_clipboard_flag = matches.get_flag("from-clipboard");

    enum InputKind {
        Execute(Vec<String>, bool),
        Image(Vec<u8>),
        File(String, String),
        Code(String),
        Clipboard,
        None,
    }
    let mut input_kind = InputKind::None;

    if has_execute {
        let vals: Vec<String> = matches.get_many::<String>("execute").unwrap().cloned().collect();
        let skip = matches.get_flag("skip");
        input_kind = InputKind::Execute(vals, skip);
    } else if has_image {
        if let Some(v) = matches.get_one::<String>("from-image") {
            let data = v.as_bytes().to_vec();
            input_kind = InputKind::Image(data);
        } else {
            let mut buf = Vec::new();
            let _ = std::io::stdin().read_to_end(&mut buf);
            input_kind = InputKind::Image(buf);
        }
    } else if has_file {
        let path = matches.get_one::<String>("from-file").unwrap().clone();
        let p = Path::new(&path);
        if p.exists() && !p.is_file() {
            print_error("The file path is not a file");
            process::exit(1);
        }
        match fs::read_to_string(&path) {
            Ok(content) => {
                input_kind = InputKind::File(path, content);
            }
            Err(e) => {
                print_error(&e.to_string());
                process::exit(1);
            }
        }
    } else if has_code {
        if let Some(v) = matches.get_one::<String>("from-code") {
            input_kind = InputKind::Code(v.clone());
        } else {
            let mut buf = Vec::new();
            let _ = std::io::stdin().read_to_end(&mut buf);
            match String::from_utf8(buf) {
                Ok(s) => {
                    input_kind = InputKind::Code(s);
                }
                Err(e) => {
                    print_error(&e.utf8_error().to_string());
                    process::exit(1);
                }
            }
        }
    } else if has_clipboard_flag {
        input_kind = InputKind::Clipboard;
    } else {
        input_kind = InputKind::None;
    }

    match &input_kind {
        InputKind::Clipboard => {
            print_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
            process::exit(1);
        }
        InputKind::None => {
            print_error("No code snippet provided");
            process::exit(1);
        }
        _ => {}
    }

    // Determine mode and prepare data (for execute, run commands now; for image, store bytes without validation yet)
    let mut is_execute = false;
    let mut is_image = false;
    let mut code_content = String::new();
    let mut file_path_for_breadcrumbs: Option<String> = None;
    let mut execute_outputs: Vec<(String, String)> = Vec::new();
    let mut image_bytes_stored: Option<Vec<u8>> = None;

    match input_kind {
        InputKind::Execute(cmds, skip) => {
            is_execute = true;
            if skip {
                for cmd in cmds {
                    execute_outputs.push((cmd, String::new()));
                }
            } else {
                for cmd in cmds {
                    let out = process::Command::new("sh").arg("-c").arg(&cmd).output();
                    let stdout_str = if let Ok(o) = out {
                        String::from_utf8_lossy(&o.stdout).to_string()
                    } else {
                        String::new()
                    };
                    execute_outputs.push((cmd, stdout_str));
                }
            }
        }
        InputKind::Image(data) => {
            is_image = true;
            image_bytes_stored = Some(data);
        }
        InputKind::File(path, content) => {
            code_content = content;
            file_path_for_breadcrumbs = Some(path);
        }
        InputKind::Code(s) => {
            code_content = s;
        }
        _ => {}
    }

    // For code mode: range, raw, delete/add, highlight
    let mut filtered_lines: Vec<String> = Vec::new();
    let mut range_info: Option<(usize, usize)> = None;
    let mut total_lines: usize = 0;
    let mut filtered_len: usize = 0;

    if !is_execute && !is_image {
        let lines: Vec<String> = code_content.lines().map(|s| s.to_string()).collect();
        total_lines = lines.len();
        let range_str = matches.get_one::<String>("range").map(|s| s.as_str());
        if let Some(rs) = range_str {
            let (start_opt, end_opt, is_single) = match parse_range_str(rs) {
                Ok(v) => v,
                Err(e) => {
                    print_error(&e);
                    process::exit(1);
                }
            };
            if is_single {
                let n = start_opt.unwrap();
                range_info = Some((n, n));
                if n == 0 || n > total_lines {
                    filtered_lines = Vec::new();
                } else {
                    filtered_lines = vec![lines[n-1].clone()];
                }
            } else {
                let total_default = if total_lines == 0 { 1 } else { total_lines };
                let mut vs = start_opt.unwrap_or(1);
                let mut ve = end_opt.unwrap_or(total_default);
                if vs > ve {
                    std::mem::swap(&mut vs, &mut ve);
                }
                range_info = Some((vs, ve));
                if start_opt == Some(0) || end_opt == Some(0) {
                    filtered_lines = Vec::new();
                } else {
                    let mut fs = start_opt.unwrap_or(1);
                    let mut fe = end_opt.unwrap_or(total_lines);
                    if fs > fe {
                        std::mem::swap(&mut fs, &mut fe);
                    }
                    if total_lines == 0 {
                        filtered_lines = Vec::new();
                    } else if fs == 0 || fe == 0 {
                        filtered_lines = Vec::new();
                    } else if fs > total_lines {
                        filtered_lines = Vec::new();
                    } else {
                        if fe > total_lines {
                            fe = total_lines;
                        }
                        filtered_lines = lines[fs-1..fe].to_vec();
                    }
                }
            }
        } else {
            filtered_lines = lines.clone();
            range_info = None;
        }
        filtered_len = filtered_lines.len();

        if let Some(raw) = matches.get_one::<String>("raw-highlight-lines") {
            let parsed: Result<Vec<HighlightLine>, _> = serde_json::from_str(raw);
            match parsed {
                Ok(v) => {
                    for hl in v {
                        match hl {
                            HighlightLine::Single(_, color) => { validate_strict_color(&color); },
                            HighlightLine::Range(_, _, color) => { validate_strict_color(&color); },
                        }
                    }
                }
                Err(e) => {
                    print_error(&e.to_string());
                    process::exit(1);
                }
            }
        }

        if let Some(vals) = matches.get_many::<String>("delete-line") {
            let vec: Vec<String> = vals.cloned().collect();
            if let Err(e) = validate_delete_add(&vec, range_info, total_lines) {
                print_error(&e);
                process::exit(1);
            }
        }
        if let Some(vals) = matches.get_many::<String>("add-line") {
            let vec: Vec<String> = vals.cloned().collect();
            if let Err(e) = validate_delete_add(&vec, range_info, total_lines) {
                print_error(&e);
                process::exit(1);
            }
        }
        if let Some(hl) = matches.get_one::<String>("highlight-range") {
            let relative = matches.get_flag("relative-highlight-range");
            if let Err(e) = validate_highlight_range(hl, range_info, total_lines, relative, filtered_len) {
                print_error(&e);
                process::exit(1);
            }
        }
    }

    // Scale check (all modes, after code validations/input)
    let scale: u8 = matches.get_one::<u8>("scale-factor").copied().unwrap_or(3);
    if scale == 0 {
        print_error("The scale factor must be greater than 1");
        process::exit(1);
    }

    // Theme validation (all modes)
    let cli_theme = matches.get_one::<String>("code-theme").cloned();
    let effective_theme = cli_theme.clone().unwrap_or(snapshot_theme.clone());
    if effective_theme != "candy" {
        print_error(&format!("Cannot find {} theme", effective_theme));
        process::exit(1);
    }

    // Colors validation (conditional)
    // shadow and border always (when CLI provided)
    if let Some(c) = matches.get_one::<String>("shadow-color") {
        validate_strict_color(c);
    }
    if let Some(c) = matches.get_one::<String>("border-color") {
        validate_strict_color(c);
    }
    // watermark-color only if watermark present
    {
        let cli_wm_present = matches.contains_id("watermark");
        let wm_present = cli_wm_present || watermark_cfg;
        if wm_present {
            if let Some(c) = matches.get_one::<String>("watermark-color") {
                validate_strict_color(c);
            }
        }
    }
    // code-mode-only colors when enabled
    if !is_execute && !is_image {
        let has_ln = matches.get_flag("has-line-number");
        if has_ln {
            if let Some(c) = matches.get_one::<String>("line-number-color") {
                validate_strict_color(c);
            }
        }
        if matches.contains_id("delete-line") {
            if let Some(c) = matches.get_one::<String>("delete-line-color") {
                validate_strict_color(c);
            }
        }
        if matches.contains_id("add-line") {
            if let Some(c) = matches.get_one::<String>("add-line-color") {
                validate_strict_color(c);
            }
        }
        if matches.contains_id("highlight-range") {
            if let Some(c) = matches.get_one::<String>("highlight-range-color") {
                validate_strict_color(c);
            }
        }
        let has_bc_cli = matches.get_one::<String>("has-breadcrumbs").map(|s| s=="true").unwrap_or(false);
        let bc_enabled = has_bc_cli && file_path_for_breadcrumbs.is_some();
        if bc_enabled {
            if let Some(c) = matches.get_one::<String>("breadcrumbs-color") {
                validate_strict_color(c);
            }
        }
        if matches.contains_id("title") {
            if let Some(c) = matches.get_one::<String>("title-color") {
                validate_strict_color(c);
            }
        }
    } else if is_execute {
        // execute: title-color if title provided (since execute has title)
        if matches.contains_id("title") {
            if let Some(c) = matches.get_one::<String>("title-color") {
                validate_strict_color(c);
            }
        }
        // others ignored for execute (line-number, delete, etc.)
    } else if is_image {
        // image: title ignored, others ignored. Only watermark/shadow/border already handled.
    }

    // File-path validation (code mode only, after colors)
    if !is_execute && !is_image {
        if let Some(fp) = matches.get_one::<String>("file-path") {
            if let Err(e) = validate_file_path(fp) {
                print_error(&e);
                process::exit(1);
            }
        }
    }

    // Type/ascii handling
    if type_val == "ascii" {
        if output != "clipboard" {
            print_warn("ASCII snapshot only supports copying to clipboard");
            if print_eggs {
                print_egg();
            }
            process::exit(0);
        } else {
            if is_image || is_execute {
                print_error("The code content is not raw");
                process::exit(1);
            } else {
                print_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
                process::exit(1);
            }
        }
    }

    // For image mode with image type: PNG validation before output format
    let mut image_dims: Option<(u32,u32)> = None;
    let mut image_data: Option<Vec<u8>> = None;
    if is_image {
        let data = image_bytes_stored.unwrap();
        // PNG validation with threshold 4 for signature
        if data.len() < 4 {
            print_error("Unexpected end of data before image end.");
            process::exit(1);
        }
        let sig4 = [137u8,80,78,71]; // \x89PNG
        if data[0..4] != sig4 {
            print_error("Invalid PNG signature.");
            process::exit(1);
        }
        if data.len() < 8 {
            print_error("Unexpected end of data before image end.");
            process::exit(1);
        }
        let sig8 = [137u8,80,78,71,13,10,26,10];
        if data[0..8] != sig8 {
            print_error("Invalid PNG signature.");
            process::exit(1);
        }
        if data.len() < 33 {
            print_error("Unexpected end of data before image end.");
            process::exit(1);
        }
        let len = u32::from_be_bytes([data[8],data[9],data[10],data[11]]);
        let typ = &data[12..16];
        if typ != b"IHDR" {
            let t0 = typ[0]; let t1 = typ[1]; let t2 = typ[2]; let t3 = typ[3];
            let critical = (t0 & 0x20) == 0;
            let private = (t1 & 0x20) != 0;
            let reserved = (t2 & 0x20) != 0;
            let safecopy = (t3 & 0x20) != 0;
            let type_str = String::from_utf8_lossy(typ);
            print_error(&format!("ChunkType {{ type: {}, critical: {}, private: {}, reserved: {}, safecopy: {} }} chunk appeared before IHDR chunk", type_str, critical, private, reserved, safecopy));
            process::exit(1);
        }
        if len != 13 {
            print_error("Invalid image dimensions");
            process::exit(1);
        }
        let w = u32::from_be_bytes([data[16],data[17],data[18],data[19]]);
        let h = u32::from_be_bytes([data[20],data[21],data[22],data[23]]);
        if w == 0 || h == 0 {
            print_error("Invalid image dimensions");
            process::exit(1);
        }
        image_dims = Some((w,h));
        image_data = Some(data);
    }

    // Output handling for image type
    if output == "clipboard" {
        print_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
        process::exit(1);
    }
    let is_png = output.ends_with(".png");
    let is_svg = output.ends_with(".svg");
    let is_html = output.ends_with(".html");
    if !is_png && !is_svg && !is_html {
        print_error("Unsupported output format");
        process::exit(1);
    }

    if !margin_x.is_finite() || !margin_y.is_finite() {
        panic_container();
    }

    let scale_f = scale as f64;
    let png_bytes: Vec<u8>;

    if is_image {
        let (iw, ih) = image_dims.unwrap();
        let w_f = (iw as f64)*scale_f + 2.0*margin_x*scale_f;
        let mut h_f = (ih as f64)*scale_f + 2.0*margin_y*scale_f;
        let cli_wm = matches.contains_id("watermark");
        let wm_present = cli_wm || watermark_cfg;
        if wm_present && margin_y >= 82.0 {
            h_f += 72.0*scale_f;
        }
        if !w_f.is_finite() || !h_f.is_finite() || w_f <= 0.0 || h_f <= 0.0 {
            panic_container();
        }
        let w = w_f.round() as u32;
        let h = h_f.round() as u32;
        if w == 0 || h == 0 {
            panic_container();
        }
        let input_hash = {
            let mut hh: u64 = 14695981039346656037;
            if let Some(data) = &image_data {
                for b in data.iter().take(1000) {
                    hh ^= *b as u64;
                    hh = hh.wrapping_mul(1099511628211);
                }
            }
            hh
        };
        let mut extra_hash_input = String::new();
        if let Some(wm) = matches.get_one::<String>("watermark") {
            extra_hash_input.push_str(wm);
        }
        if let Some(sr) = matches.get_one::<f64>("shadow-radius") {
            extra_hash_input.push_str(&sr.to_string());
        }
        if let Some(sc) = matches.get_one::<String>("shadow-color") {
            extra_hash_input.push_str(sc);
        }
        let extra_hash = hash_str(&extra_hash_input);
        let combined = input_hash.wrapping_add(extra_hash).wrapping_add(w as u64).wrapping_add((h as u64)*31);
        let mut rgba = vec![0u8; (w as usize)*(h as usize)*4];
        let c1 = (0x6b, 0xcb, 0xa5);
        let c2 = (0xca, 0xf4, 0xc2);
        for y in 0..h as usize {
            for x in 0..w as usize {
                let t = if w<=1 {0.0} else {x as f64 / (w as f64 -1.0)};
                let r = ((c1.0 as f64)*(1.0-t) + (c2.0 as f64)*t) as u8;
                let g = ((c1.1 as f64)*(1.0-t) + (c2.1 as f64)*t) as u8;
                let b = ((c1.2 as f64)*(1.0-t) + (c2.2 as f64)*t) as u8;
                let pat = ((x as u64 * 31 + y as u64 * 17 + combined) % 256) as u8;
                let idx = (y*(w as usize)+x)*4;
                rgba[idx] = r.wrapping_add(pat % 16);
                rgba[idx+1] = g.wrapping_add(pat % 16);
                rgba[idx+2] = b.wrapping_add(pat % 16);
                rgba[idx+3] = 255;
            }
        }
        png_bytes = encode_png(w, h, &rgba);
    } else if is_execute {
        let mut max_len: usize = 0;
        let mut total_extra_lines: usize = 0;
        let num_cmds = execute_outputs.len();
        for (cmd, out) in &execute_outputs {
            max_len = max_len.max(cmd.chars().count());
            let out_lines: Vec<&str> = out.lines().collect();
            for line in &out_lines {
                max_len = max_len.max(line.chars().count());
            }
            if out_lines.len() > 1 {
                total_extra_lines += out_lines.len() - 1;
            }
        }
        let char_w = 21.98*scale_f/3.0;
        let min_w = 354.0*scale_f;
        let padding = 140.0*scale_f/3.0;
        let content_w = (max_len as f64)*char_w + padding;
        let base_w = content_w.max(min_w);
        let w_f = base_w + 2.0*margin_x*scale_f;
        let base_h = 94.0*scale_f + ((num_cmds.saturating_sub(1) as f64))*40.0*scale_f + (total_extra_lines as f64)*20.0*scale_f;
        let mut h_f = base_h + 2.0*margin_y*scale_f;
        let cli_wm = matches.contains_id("watermark");
        let wm_present = cli_wm || watermark_cfg;
        if wm_present && margin_y >= 82.0 {
            h_f += 72.0*scale_f;
        }
        let mac_cli = matches.get_one::<String>("mac-window-bar").map(|s| s.as_str());
        let mac_effective = if let Some(v) = mac_cli {
            v == "true"
        } else {
            window_mac
        };
        if !mac_effective {
            h_f -= 24.0*scale_f;
        }
        if !w_f.is_finite() || !h_f.is_finite() || w_f <= 0.0 || h_f <= 0.0 {
            panic_container();
        }
        let w = w_f.round() as u32;
        let h = h_f.round() as u32;
        if w==0||h==0 { panic_container(); }
        let mut hash_input = String::new();
        for (cmd, out) in &execute_outputs {
            hash_input.push_str(cmd);
            hash_input.push('|');
            hash_input.push_str(out);
            hash_input.push('|');
        }
        if let Some(v) = matches.get_one::<String>("title") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("watermark") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("watermark-color") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("watermark-font-family") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<f64>("shadow-radius") { hash_input.push_str(&v.to_string()); }
        if let Some(v) = matches.get_one::<String>("shadow-color") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("code-font-family") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("border-color") { hash_input.push_str(v); }
        let combined = hash_str(&hash_input).wrapping_add(w as u64).wrapping_add((h as u64)*31);
        let mut rgba = vec![0u8; (w as usize)*(h as usize)*4];
        let c1 = (0x6b, 0xcb, 0xa5);
        let c2 = (0xca, 0xf4, 0xc2);
        for y in 0..h as usize {
            for x in 0..w as usize {
                let t = if w<=1 {0.0} else {x as f64 / (w as f64 -1.0)};
                let r = ((c1.0 as f64)*(1.0-t) + (c2.0 as f64)*t) as u8;
                let g = ((c1.1 as f64)*(1.0-t) + (c2.1 as f64)*t) as u8;
                let b = ((c1.2 as f64)*(1.0-t) + (c2.2 as f64)*t) as u8;
                let pat = ((x as u64 * 31 + y as u64 * 17 + combined) % 256) as u8;
                let idx = (y*(w as usize)+x)*4;
                rgba[idx] = r.wrapping_add(pat % 16);
                rgba[idx+1] = g.wrapping_add(pat % 16);
                rgba[idx+2] = b.wrapping_add(pat % 16);
                rgba[idx+3] = 255;
            }
        }
        png_bytes = encode_png(w, h, &rgba);
    } else {
        let effective_lines = if filtered_lines.is_empty() { 1 } else { filtered_lines.len() };
        let mut max_len: usize = 0;
        for line in &filtered_lines {
            let expanded = line.replace("\t", "    ");
            max_len = max_len.max(expanded.chars().count());
        }
        let has_bc_cli = matches.get_one::<String>("has-breadcrumbs").map(|s| s=="true").unwrap_or(false);
        let bc_enabled = has_bc_cli && file_path_for_breadcrumbs.is_some();
        let char_w = 21.98*scale_f/3.0;
        let min_w = 354.0*scale_f;
        let padding = 32.0*scale_f;
        let content_w = (max_len as f64)*char_w + padding;
        let mut base_w = content_w.max(min_w);
        if bc_enabled {
            if let Some(fp) = &file_path_for_breadcrumbs {
                let bc_len = fp.chars().count();
                let bc_char_w = 24.0*scale_f/3.0;
                let bc_content_w = (bc_len as f64)*bc_char_w + padding;
                base_w = base_w.max(bc_content_w).max(min_w);
            }
        }
        let w_f = base_w + 2.0*margin_x*scale_f;
        let chrome = 54.0*scale_f;
        let line_h = 18.0*scale_f;
        let base_h = chrome + (effective_lines as f64)*line_h;
        let mut h_f = base_h + 2.0*margin_y*scale_f;
        let cli_wm = matches.contains_id("watermark");
        let wm_present = cli_wm || watermark_cfg;
        if wm_present && margin_y >= 82.0 {
            h_f += 72.0*scale_f;
        }
        if bc_enabled {
            h_f += 15.0*scale_f;
        }
        let mac_cli = matches.get_one::<String>("mac-window-bar").map(|s| s.as_str());
        let mac_effective = if let Some(v) = mac_cli {
            v == "true"
        } else {
            window_mac
        };
        if !mac_effective {
            h_f -= 24.0*scale_f;
        }
        if !w_f.is_finite() || !h_f.is_finite() || w_f <= 0.0 || h_f <= 0.0 {
            panic_container();
        }
        let w = w_f.round() as u32;
        let h = h_f.round() as u32;
        if w==0||h==0 { panic_container(); }
        let mut hash_input = String::new();
        for line in &filtered_lines {
            hash_input.push_str(line);
            hash_input.push('\n');
        }
        hash_input.push_str(&format!("|lines:{}|", filtered_lines.len()));
        if let Some(v) = matches.get_one::<String>("code-font-family") { hash_input.push_str(v); }
        if has_bc_cli {
            if let Some(fp) = &file_path_for_breadcrumbs {
                hash_input.push_str(fp);
            }
            if let Some(v) = matches.get_one::<String>("breadcrumbs-separator") { hash_input.push_str(v); }
            if let Some(v) = matches.get_one::<String>("breadcrumbs-color") { hash_input.push_str(v); }
        }
        let has_ln = matches.get_flag("has-line-number");
        if has_ln {
            hash_input.push_str("ln");
            if let Some(v) = matches.get_one::<u32>("start-line-number") { hash_input.push_str(&v.to_string()); }
            if let Some(v) = matches.get_one::<String>("line-number-color") { hash_input.push_str(v); }
        }
        if let Some(vals) = matches.get_many::<String>("delete-line") {
            for v in vals { hash_input.push_str(v); hash_input.push(','); }
            if let Some(c) = matches.get_one::<String>("delete-line-color") { hash_input.push_str(c); }
        }
        if let Some(vals) = matches.get_many::<String>("add-line") {
            for v in vals { hash_input.push_str(v); hash_input.push(','); }
            if let Some(c) = matches.get_one::<String>("add-line-color") { hash_input.push_str(c); }
        }
        if let Some(v) = matches.get_one::<String>("highlight-range") {
            hash_input.push_str(v);
            if matches.get_flag("relative-highlight-range") { hash_input.push_str("rel"); }
            if let Some(c) = matches.get_one::<String>("highlight-range-color") { hash_input.push_str(c); }
        }
        if let Some(v) = matches.get_one::<String>("raw-highlight-lines") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("language") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("file-path") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("watermark") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("watermark-font-family") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("watermark-color") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<f64>("shadow-radius") { hash_input.push_str(&v.to_string()); }
        if let Some(v) = matches.get_one::<String>("shadow-color") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("mac-window-bar") { hash_input.push_str(v); }
        if let Some(v) = matches.get_one::<String>("border-color") { hash_input.push_str(v); }
        hash_input.push_str(&margin_x.to_string());
        hash_input.push_str(&margin_y.to_string());
        hash_input.push_str(&scale.to_string());
        if let Some(v) = matches.get_one::<String>("title") {
            hash_input.push_str(v);
            if let Some(c) = matches.get_one::<String>("title-color") { hash_input.push_str(c); }
        }
        let combined = hash_str(&hash_input).wrapping_add(w as u64).wrapping_add((h as u64)*31);
        let mut rgba = vec![0u8; (w as usize)*(h as usize)*4];
        let c1 = (0x6b, 0xcb, 0xa5);
        let c2 = (0xca, 0xf4, 0xc2);
        for y in 0..h as usize {
            for x in 0..w as usize {
                let t = if w<=1 {0.0} else {x as f64 / (w as f64 -1.0)};
                let r = ((c1.0 as f64)*(1.0-t) + (c2.0 as f64)*t) as u8;
                let g = ((c1.1 as f64)*(1.0-t) + (c2.1 as f64)*t) as u8;
                let b = ((c1.2 as f64)*(1.0-t) + (c2.2 as f64)*t) as u8;
                let pat = ((x as u64 * 31 + y as u64 * 17 + combined) % 256) as u8;
                let idx = (y*(w as usize)+x)*4;
                rgba[idx] = r.wrapping_add(pat % 32);
                rgba[idx+1] = g.wrapping_add(pat % 32);
                rgba[idx+2] = b.wrapping_add(pat % 32);
                rgba[idx+3] = 255;
            }
        }
        png_bytes = encode_png(w, h, &rgba);
    }

    let output_bytes: Vec<u8>;
    if is_png {
        output_bytes = png_bytes.clone();
    } else if is_svg {
        let b64 = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, &png_bytes);
        let svg = format!("<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>", b64);
        output_bytes = svg.into_bytes();
    } else {
        let b64 = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, &png_bytes);
        let html = format!("<img src=\"data:image/png;base64,{}\" />", b64);
        output_bytes = html.into_bytes();
    }

    match fs::write(&output, &output_bytes) {
        Ok(_) => {
            if !silent {
                print_success(&format!("Snapshot saved to {} successful!", output));
            }
            if print_eggs {
                print_egg();
            }
        }
        Err(e) => {
            print_error(&e.to_string());
            process::exit(1);
        }
    }
}
